    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(3)]
    [InlineData(4)]
    [InlineData(5)]
    [InlineData(6)]
    [InlineData(7)]
    [InlineData(8)]
    [InlineData(9)]
    public void CompleteProfilesHeaderAndAlignedTagsMatchThePinnedNativeGammaBranch(int fixtureIndex)
    {
        NativeFixture fixture = NativeFixtures[fixtureIndex];
        foreach (bool grayscale in new[] { false, true })
        {
            byte[] profile = Create(grayscale, fixture.Gamma);
            Assert.Equal(grayscale ? fixture.GraySize : fixture.RgbSize, profile.Length);
            Assert.Equal(grayscale ? fixture.GraySha256 : fixture.RgbSha256,
                Convert.ToHexString(SHA256.HashData(profile)));
            Assert.Equal(grayscale ? fixture.GrayId : fixture.RgbId, Convert.ToHexString(profile.AsSpan(84, 16)));
            Assert.Equal(profile.Length, Int32(profile, 0));
            Assert.Equal("jxl ", Signature(profile, 4));
            Assert.Equal(0x04400000, Int32(profile, 8));
            Assert.Equal("mntr", Signature(profile, 12));
            Assert.Equal(grayscale ? "GRAY" : "RGB ", Signature(profile, 16));
            Assert.Equal("XYZ ", Signature(profile, 20));
            Assert.Equal(new[] { 2019, 12, 1, 0, 0, 0 },
                Enumerable.Range(0, 6).Select(index => UInt16(profile, 24 + index * 2)));
            Assert.Equal("acsp", Signature(profile, 36));
            Assert.Equal("APPL", Signature(profile, 40));
            Assert.All(profile[44..68], value => Assert.Equal(0, value));
            Assert.Equal(new[] { 0x0000f6d6, 0x00010000, 0x0000d32d },
                Enumerable.Range(0, 3).Select(index => Int32(profile, 68 + index * 4)));
            Assert.Equal("jxl ", Signature(profile, 80));
            Assert.All(profile[100..128], value => Assert.Equal(0, value));
            Dictionary<string, Tag> tags = Tags(profile);
            Assert.Equal(grayscale
                ? new[] { "desc", "cprt", "wtpt", "kTRC" }
                : new[] { "desc", "cprt", "wtpt", "chad", "rXYZ", "gXYZ", "bXYZ", "rTRC", "gTRC", "bTRC" },
                tags.Keys);
            string description = (grayscale ? "Gra_D65_Per_g" : "RGB_D65_SRG_Per_g") + fixture.Suffix;
            Assert.Equal(description, Text(profile, tags["desc"]));
            Assert.Equal("CC0", Text(profile, tags["cprt"]));
            Assert.Equal(2, IccProfile.LookupTransferFunction(profile, TestContext.Current.CancellationToken));
            Tag white = tags["wtpt"];
            Assert.Equal("XYZ ", Signature(profile, white.Offset));
            Assert.Equal(20, white.Length);
            double[] expectedWhite = grayscale
                ? [0.3127 / 0.3290, 1, (1 - 0.3127 - 0.3290) / 0.3290] : [0.964203, 1, 0.824905];
            for (int channel = 0; channel < 3; channel++)
                AssertClose(expectedWhite[channel], Fixed(profile, white.Offset + 8 + channel * 4),
                    0.5 / 65536, $"media white channel {channel}");
            Assert.Equal(grayscale ? 4 : 8, tags.Values.Distinct().Count());
            if (!grayscale)
            {
                Assert.Equal("sf32", Signature(profile, tags["chad"].Offset));
                Assert.Equal(44, tags["chad"].Length);
                foreach (string color in new[] { "r", "g", "b" })
                {
                    Assert.Equal("XYZ ", Signature(profile, tags[color + "XYZ"].Offset));
                    Assert.Equal(20, tags[color + "XYZ"].Length);
                }
            }
        }
    }

    [Fact]
    public void DescriptionsAndProfileIdsAreIndependentOfTheCurrentCulture()
    {
        CultureInfo original = CultureInfo.CurrentCulture;
        try
        {
            CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo("fr-FR");
            foreach (NativeFixture fixture in NativeFixtures)
            {
                Assert.Equal(fixture.RgbSha256, Convert.ToHexString(SHA256.HashData(Create(false, fixture.Gamma))));
                Assert.Equal(fixture.GraySha256, Convert.ToHexString(SHA256.HashData(Create(true, fixture.Gamma))));
            }
        }
        finally
        {
            CultureInfo.CurrentCulture = original;
        }
    }

    [Theory]
    [InlineData(double.NaN)]
    [InlineData(double.NegativeInfinity)]
    [InlineData(double.PositiveInfinity)]
    [InlineData(-1)]
    [InlineData(-0.0)]
    [InlineData(double.Epsilon)]
    [InlineData(0.9999999999999999)]
    [InlineData(8192.000000000002)]
    [InlineData(double.MaxValue)]
    public void FactoriesRejectNonfiniteAndOutOfRangeDecodingExponents(double gamma)
    {
        foreach (bool grayscale in new[] { false, true })
        {
            var error = Assert.Throws<ArgumentOutOfRangeException>(() => Create(grayscale, gamma));
            Assert.Equal("gamma", error.ParamName);
        }
    }

    [Theory]
    [InlineData(false, 1)]
    [InlineData(true, 1)]
    [InlineData(false, 2.2)]
    [InlineData(true, 2.2)]
    [InlineData(false, 8192)]
    [InlineData(true, 8192)]
    public void EachCallOwnsDeterministicStorageAndItsIdIsTheIndependentIccMd5Digest(bool grayscale, double gamma)
    {
        byte[] first = Create(grayscale, gamma), second = Create(grayscale, gamma);
        Assert.NotSame(first, second);
        Assert.Equal(first, second);
        Array.Fill(first, (byte)0xdd);
        Assert.Equal(second, Create(grayscale, gamma));
        byte[] id = second[84..100];
        Array.Clear(second, 44, 4);
        Array.Clear(second, 64, 4);
        Array.Clear(second, 84, 16);
        Assert.Equal(id, MD5.HashData(second));
    }

    [Theory]
    [InlineData(1)]
    [InlineData(1.0000076283945313)]
    [InlineData(1.4648208022117615)]
    [InlineData(1.8)]
    [InlineData(2.2)]
    [InlineData(2.4)]
    [InlineData(2.6)]
    [InlineData(8192)]
    public void ParametricTypeZeroStoresTheDecodingExponentAndMatchesAnIndependentPowerOracle(double gamma)
    {
        foreach (bool grayscale in new[] { false, true })
        {
            byte[] profile = Create(grayscale, gamma);
            Dictionary<string, Tag> tags = Tags(profile);
            Tag curve = tags[grayscale ? "kTRC" : "rTRC"];
            Assert.Equal("para", Signature(profile, curve.Offset));
            Assert.Equal(16, curve.Length);
            Assert.Equal(0, UInt16(profile, curve.Offset + 8));
            Assert.Equal(0, UInt16(profile, curve.Offset + 10));
            // The upstream generic branch stores the inverse of its encoding
            // gamma after rounding through float, then serializes s15Fixed16.
            int expected = (int)Math.Round((double)(float)(1 / (1 / gamma)) * 65536,
                MidpointRounding.AwayFromZero);
            Assert.Equal(expected, Int32(profile, curve.Offset + 12));
            double serializedGamma = Fixed(profile, curve.Offset + 12);
            foreach (double sample in Enumerable.Range(0, 256).Select(value => value / 255.0)
                .Concat(new[] { 1e-8, 0.04045, 0.5, 0.999, 0.9999, 0.99999 }))
                AssertClose(Math.Pow(sample, gamma), Math.Pow(sample, serializedGamma), 0.000006,
                    $"decoded sample {sample:R}, gamma {gamma:R}");
            Assert.Equal(0, Math.Pow(0, serializedGamma));
            Assert.Equal(1, Math.Pow(1, serializedGamma));
            if (!grayscale)
            {
                Assert.Equal(curve, tags["gTRC"]);
                Assert.Equal(curve, tags["bTRC"]);
            }
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void ReciprocalRoundTripMatchesThePinnedNativeFixedExponent(bool grayscale)
    {
        // At this boundary, casting the original gamma directly to float
        // would emit 95999. The pinned native reciprocal round trip emits
        // 95998; keep its literal value independent of the general oracle.
        byte[] profile = Create(grayscale, 1.4648208022117615);
        Tag curve = Tags(profile)[grayscale ? "kTRC" : "rTRC"];
        Assert.Equal(95998, Int32(profile, curve.Offset + 12));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void GammaOneRetainsTheGenericProfileWithoutInferringTheNamedLinearTransfer(bool grayscale)
    {
        byte[] generic = Create(grayscale, 1);
        byte[] linear = grayscale ? JpegliIccProfiles.CreateLinearSrgbGrayscaleProfile()
            : JpegliIccProfiles.CreateLinearSrgbProfile();
        Assert.False(generic.SequenceEqual(linear));
        Assert.Equal(2, IccProfile.LookupTransferFunction(generic, TestContext.Current.CancellationToken));
        Assert.Equal(grayscale ? 2 : 8,
            IccProfile.LookupTransferFunction(linear, TestContext.Current.CancellationToken));
        Assert.Equal(16, Tags(generic)[grayscale ? "kTRC" : "rTRC"].Length);
    }

    [Fact]
    public void RgbMatrixMediaWhiteAndChromaticAdaptationRemainTheSrgbD65ToD50Transform()
    {
        byte[] profile = Create(false, 2.2), linear = JpegliIccProfiles.CreateLinearSrgbProfile();
        Dictionary<string, Tag> tags = Tags(profile), linearTags = Tags(linear);
        foreach (string signature in new[] { "wtpt", "chad", "rXYZ", "gXYZ", "bXYZ" })
        {
            Tag actual = tags[signature], expected = linearTags[signature];
            Assert.Equal(linear[expected.Offset..(expected.Offset + expected.Length)],
                profile[actual.Offset..(actual.Offset + actual.Length)]);
        }
        double[] samples = [0, 0.01, 0.25, 0.5, 0.75, 1];
        foreach (double r in samples)
            foreach (double g in samples)
                foreach (double b in samples)
                {
                    double lr = Math.Pow(r, 2.2), lg = Math.Pow(g, 2.2), lb = Math.Pow(b, 2.2);
                    double[] expected = [0.4360747 * lr + 0.3850649 * lg + 0.1430804 * lb,
                        0.2225045 * lr + 0.7168786 * lg + 0.0606169 * lb,
                        0.0139322 * lr + 0.0971045 * lg + 0.7141733 * lb];
                    double[] encoded = [r, g, b];
                    for (int row = 0; row < 3; row++)
                    {
                        double actual = 0;
                        for (int channel = 0; channel < 3; channel++)
                        {
                            string color = new[] { "r", "g", "b" }[channel];
                            actual += Fixed(profile, tags[color + "XYZ"].Offset + 8 + row * 4)
                                * Math.Pow(encoded[channel], Fixed(profile, tags[color + "TRC"].Offset + 12));
                        }
                        AssertClose(expected[row], actual, 0.0001,
                            $"D50 XYZ channel {row}, gamma RGB ({r:R}, {g:R}, {b:R})");
                    }
                }
    }

    [Theory]
    [InlineData(0, JpegColorSpace.YCbCr, false, 0)]
    [InlineData(1, JpegColorSpace.YCbCr, true, 2)]
    [InlineData(2, JpegColorSpace.YCbCr, true, 0)]
    [InlineData(0, JpegColorSpace.Rgb, true, 2)]
    [InlineData(1, JpegColorSpace.Rgb, false, 0)]
    [InlineData(2, JpegColorSpace.Rgb, true, 0)]
    [InlineData(0, JpegColorSpace.Grayscale, false, 0)]
    [InlineData(1, JpegColorSpace.Grayscale, true, 0)]
    [InlineData(2, JpegColorSpace.Grayscale, true, 2)]
    public void EmbeddingPreservesCodingDecodedPixelsAndPaddedTypedInputsAcrossScans(
        int sourceKind, JpegColorSpace colorSpace, bool progressive, int refinement)
    {
        const int width = 19, height = 17;
        bool grayscale = colorSpace == JpegColorSpace.Grayscale;
        PixelComponentLayout layout = grayscale ? PixelComponentLayout.Gray : PixelComponentLayout.Bgra;
        int components = grayscale ? 1 : 4, stride = width * components + 5;
        Array pixels = Source(sourceKind, width, height, components, stride), originalPixels = (Array)pixels.Clone();
        byte[] profile = Create(grayscale, 2.2);
        byte[] backing = Enumerable.Repeat((byte)0x5b, profile.Length + 11).ToArray();
        profile.CopyTo(backing, 3);
        byte[] originalBacking = backing.ToArray();
        var options = new JpegliEncoderOptions
        {
            ColorSpace = colorSpace, IccProfile = backing.AsMemory(3, profile.Length),
            InferCicpTransferFunctionFromIccProfile = true, Distance = 1.375f,
            SmoothingFactor = 37, Progressive = progressive,
            ProgressiveRefinementBits = refinement, RestartInterval = 2
        };
        byte[] actual = Encode(pixels, width, height, layout, options, stride);
        (byte[]? embedded, byte[] coding, _) = ReadIccAndCoding(actual);
        Assert.Equal(profile, embedded);
        byte[] reference = Encode(pixels, width, height, layout, options with { IccProfile = default }, stride);
        Assert.Null(ReadIccAndCoding(reference).Icc);
        Assert.Equal(coding, ReadIccAndCoding(reference).Coding);
        Assert.Equal(actual, Encode(pixels, width, height, layout,
            options with { InferCicpTransferFunctionFromIccProfile = false }, stride));
        ColorComponents channels = grayscale ? ColorComponents.Grey : ColorComponents.RedGreenBlue;
        ImageResult decoded = ImageResult.FromMemory(actual, channels);
        Assert.Equal((width, height), (decoded.Width, decoded.Height));
        Assert.Equal(ImageResult.FromMemory(reference, channels).Data, decoded.Data);
        JpegDocument document = JpegDocument.Read(actual, progressive, 2, refinement);
        Assert.Equal(grayscale ? 1 : 3, document.Components.Count);
        using var destination = new MemoryStream();
        using var output = new WriteOnlyStream(destination);
        Encode(output, pixels, width, height, layout, options, stride, TestContext.Current.CancellationToken);
        Assert.Equal(actual, destination.ToArray());
        Assert.False(output.Closed);
        Assert.Equal(originalBacking, backing);
        Assert.Equal(originalPixels.Cast<object>(), pixels.Cast<object>());
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void CancellationBeforeOrAfterTheIccMarkerLeavesTheNonseekableStreamOpen(bool grayscale)
    {
        byte[] pixels = grayscale ? [0, 127, 255] : [0, 127, 255, 255, 127, 0, 127, 0, 255];
        PixelComponentLayout layout = grayscale ? PixelComponentLayout.Gray : PixelComponentLayout.Rgb;
        int stride = grayscale ? 3 : 9;
        byte[] profile = Create(grayscale, 2.4);
        var options = new JpegliEncoderOptions { IccProfile = profile, InferCicpTransferFunctionFromIccProfile = true };
        byte[] complete = Encode(pixels, 3, 1, layout, options, stride);
        using var destination = new MemoryStream();
        using (var output = new WriteOnlyStream(destination))
        {
            var canceled = new CancellationToken(true);
            var error = Assert.Throws<OperationCanceledException>(() =>
                Encode(output, pixels, 3, 1, layout, options, stride, canceled));
            Assert.Equal(canceled, error.CancellationToken);
            Assert.Equal(0, destination.Length);
            Assert.False(output.Closed);
        }
        int boundary = ReadIccAndCoding(complete).IccEnd;
        using var cancellation = CancellationTokenSource.CreateLinkedTokenSource(TestContext.Current.CancellationToken);
        using var stream = new WriteOnlyStream(destination, () =>
        {
            if (destination.Length >= boundary)
                cancellation.Cancel();
        });
        var interrupted = Assert.Throws<OperationCanceledException>(() =>
            Encode(stream, pixels, 3, 1, layout, options, stride, cancellation.Token));
        Assert.Equal(cancellation.Token, interrupted.CancellationToken);
        Assert.Equal(complete[..boundary], destination.ToArray());
        Assert.False(stream.Closed);
        Assert.Equal(Create(grayscale, 2.4), profile);
    }

    private static byte[] Create(bool grayscale, double gamma) => grayscale
        ? JpegliIccProfiles.CreateGammaGrayscaleProfile(gamma) : JpegliIccProfiles.CreateGammaSrgbProfile(gamma);

    private static Dictionary<string, Tag> Tags(byte[] profile)
    {
        int count = Int32(profile, 128), tableEnd = 132 + count * 12;
        var result = new Dictionary<string, Tag>();
        var extents = new HashSet<Tag>();
        for (int index = 0; index < count; index++)
        {
            int entry = 132 + index * 12;
            var tag = new Tag(Int32(profile, entry + 4), Int32(profile, entry + 8));
            Assert.Equal(0, tag.Offset % 4);
            Assert.InRange(tag.Offset, tableEnd, profile.Length - 8);
            Assert.InRange(tag.Length, 8, profile.Length - tag.Offset);
            Assert.Equal(0, Int32(profile, tag.Offset + 4));
            Assert.True(result.TryAdd(Signature(profile, entry), tag));
            extents.Add(tag);
        }
        Tag[] ordered = extents.OrderBy(tag => tag.Offset).ToArray();
        Assert.Equal(tableEnd, ordered[0].Offset);
        for (int index = 1; index < ordered.Length; index++)
        {
            int previousEnd = ordered[index - 1].Offset + ordered[index - 1].Length;
            Assert.Equal((previousEnd + 3) & ~3, ordered[index].Offset);
            Assert.All(profile[previousEnd..ordered[index].Offset], value => Assert.Equal(0, value));
        }
        Assert.Equal(profile.Length, ordered[^1].Offset + ordered[^1].Length);
        return result;
    }

    private static string Text(byte[] profile, Tag tag)
    {
        Assert.Equal("mluc", Signature(profile, tag.Offset));
        Assert.Equal(1, Int32(profile, tag.Offset + 8));
        Assert.Equal(12, Int32(profile, tag.Offset + 12));
        Assert.Equal("enUS", Signature(profile, tag.Offset + 16));
        int length = Int32(profile, tag.Offset + 20), offset = Int32(profile, tag.Offset + 24);
        Assert.Equal(28, offset);
        Assert.Equal(0, length % 2);
        Assert.Equal((offset + length + 3) & ~3, tag.Length);
        Assert.All(profile[(tag.Offset + offset + length)..(tag.Offset + tag.Length)], value => Assert.Equal(0, value));
        return Encoding.BigEndianUnicode.GetString(profile, tag.Offset + offset, length);
    }

    private static (byte[]? Icc, byte[] Coding, int IccEnd) ReadIccAndCoding(byte[] jpeg)
    {
        Assert.Equal(new byte[] { 0xff, 0xd8 }, jpeg[..2]);
        using var coding = new MemoryStream();
        coding.Write(jpeg.AsSpan(0, 2));
        byte[]? profile = null;
        int offset = 2, iccEnd = 0;
        while (jpeg[offset + 1] != 0xda)
        {
            Assert.Equal(0xff, jpeg[offset]);
            int length = UInt16(jpeg, offset + 2);
            Assert.InRange(length, 2, jpeg.Length - offset - 2);
            int end = offset + 2 + length;
            if (jpeg[offset + 1] == 0xe2)
            {
                Assert.Null(profile);
                Assert.True(jpeg.AsSpan(offset + 4, 12).SequenceEqual("ICC_PROFILE\0"u8));
                Assert.Equal(1, jpeg[offset + 16]);
                Assert.Equal(1, jpeg[offset + 17]);
                profile = jpeg[(offset + 18)..end];
                iccEnd = end;
            }
            else
                coding.Write(jpeg.AsSpan(offset, end - offset));
            offset = end;
        }
        coding.Write(jpeg.AsSpan(offset));
        return (profile, coding.ToArray(), iccEnd);
    }

    private static Array Source(int kind, int width, int height, int components, int stride)
    {
        int rowLength = width * components;
        byte[] bytes = Enumerable.Repeat((byte)0xad, (height - 1) * stride + rowLength).ToArray();
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                for (int channel = 0; channel < (components == 1 ? 1 : 3); channel++)
                    bytes[y * stride + x * components + channel] = (byte)((x * 73 + y * 29 + channel * 61) % 256);
        return kind switch
        {
            0 => bytes,
            1 => bytes.Select((value, index) => (ushort)Math.Clamp(value * 257 + index % 47 - 23, 0, 65535)).ToArray(),
            _ => bytes.Select((value, index) => index % stride >= rowLength || components == 4 && index % stride % 4 == 3
                ? float.NaN : Math.Clamp(value / 255f + (index % 47 - 23) / 65535f, 0f, 1f)).ToArray()
        };
    }

    private static byte[] Encode(Array pixels, int width, int height, PixelComponentLayout layout,
        JpegliEncoderOptions options, int stride) => pixels switch
    {
        byte[] bytes => JpegliEncoder.Encode(bytes, width, height, (PixelLayout)(int)layout,
            options, stride, TestContext.Current.CancellationToken),
        ushort[] words => JpegliEncoder.Encode(words, width, height, layout,
            options, stride, TestContext.Current.CancellationToken),
        _ => JpegliEncoder.Encode((float[])pixels, width, height, layout,
            options, stride, TestContext.Current.CancellationToken)
    };

    private static void Encode(Stream output, Array pixels, int width, int height, PixelComponentLayout layout,
        JpegliEncoderOptions options, int stride, CancellationToken cancellationToken)
    {
        if (pixels is byte[] bytes)
            JpegliEncoder.Encode(output, bytes, width, height, (PixelLayout)(int)layout, options, stride, cancellationToken);
        else if (pixels is ushort[] words)
            JpegliEncoder.Encode(output, words, width, height, layout, options, stride, cancellationToken);
        else
            JpegliEncoder.Encode(output, (float[])pixels, width, height, layout, options, stride, cancellationToken);
    }

    private static int Int32(byte[] bytes, int offset) => BinaryPrimitives.ReadInt32BigEndian(bytes.AsSpan(offset, 4));
    private static int UInt16(byte[] bytes, int offset) => BinaryPrimitives.ReadUInt16BigEndian(bytes.AsSpan(offset, 2));
    private static double Fixed(byte[] bytes, int offset) => Int32(bytes, offset) / 65536.0;
    private static string Signature(byte[] bytes, int offset) => Encoding.ASCII.GetString(bytes, offset, 4);
    private sealed record Tag(int Offset, int Length);
    private sealed record NativeFixture(double Gamma, string Suffix, int RgbSize, int GraySize,
        string RgbSha256, string RgbId, string GraySha256, string GrayId);
    private static void AssertClose(double expected, double actual, double tolerance, string label) =>
        Assert.True(double.IsFinite(actual) && Math.Abs(expected - actual) <= tolerance,
            $"{label}: expected {expected:R}, actual {actual:R}, tolerance {tolerance:R}.");
}
